import re

_NUM = r"([0-9]+(?:[.,][0-9]+)?)"
_DATE = re.compile(rf"(?:{_NUM}Y)?(?:{_NUM}M)?(?:{_NUM}W)?(?:{_NUM}D)?")
_TIME = re.compile(rf"(?:{_NUM}H)?(?:{_NUM}M)?(?:{_NUM}S)?")
_FACTORS = [365 * 86400, 30 * 86400, 7 * 86400, 86400, 3600, 60, 1]


def parse_duration(s: str) -> float:
    if not isinstance(s, str) or not s.startswith("P"):
        raise ValueError("duration must start with 'P'")
    body = s[1:]
    if not body:
        raise ValueError("no components")
    if "T" in body:
        date_part, _, time_part = body.partition("T")
        if not time_part:
            raise ValueError("'T' must be followed by a time component")
    else:
        date_part, time_part = body, ""
    dm = _DATE.fullmatch(date_part)
    tm = _TIME.fullmatch(time_part)
    if not dm or not tm:
        raise ValueError("malformed duration")
    values = list(dm.groups()) + list(tm.groups())
    present = [i for i, v in enumerate(values) if v is not None]
    if not present:
        raise ValueError("no components")
    total = 0.0
    for i in present:
        v = values[i]
        if ("." in v or "," in v) and i != present[-1]:
            raise ValueError("only the last component may be fractional")
        total += float(v.replace(",", ".")) * _FACTORS[i]
    return total

import re

_VER = re.compile(
    r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?"
)


def _parse(text):
    m = _VER.fullmatch(text)
    if not m:
        raise ValueError(f"invalid version: {text!r}")
    major, minor, patch, pre = m.groups()
    return (int(major), int(minor), int(patch)), (tuple(pre.split(".")) if pre else ())


def _cmp_pre(a, b):
    if a == b:
        return 0
    if not a:
        return 1
    if not b:
        return -1
    for x, y in zip(a, b):
        if x == y:
            continue
        xn, yn = x.isdigit(), y.isdigit()
        if xn and yn:
            return -1 if int(x) < int(y) else 1
        if xn != yn:
            return -1 if xn else 1
        return -1 if x < y else 1
    return -1 if len(a) < len(b) else 1


def _cmp(a, b):
    if a[0] != b[0]:
        return -1 if a[0] < b[0] else 1
    return _cmp_pre(a[1], b[1])


def _check(token, v):
    if token == "*":
        return True
    for op in (">=", "<=", ">", "<", "=", "^", "~"):
        if token.startswith(op):
            ver = _parse(token[len(op):])
            break
    else:
        op, ver = "=", _parse(token)
    c = _cmp(v, ver)
    if op == "=":
        return c == 0
    if op == ">":
        return c > 0
    if op == ">=":
        return c >= 0
    if op == "<":
        return c < 0
    if op == "<=":
        return c <= 0
    major, minor, patch = ver[0]
    if op == "~":
        upper = (major, minor + 1, 0)
    elif major > 0:
        upper = (major + 1, 0, 0)
    elif minor > 0:
        upper = (0, minor + 1, 0)
    else:
        upper = (0, 0, patch + 1)
    return c >= 0 and _cmp(v, (upper, ())) < 0


def satisfies(version: str, range_expr: str) -> bool:
    v = _parse(version)
    if not range_expr.strip():
        raise ValueError("empty range")
    matched = False
    for part in range_expr.split("||"):
        tokens = part.split()
        if not tokens:
            raise ValueError("empty comparator set")
        results = [_check(t, v) for t in tokens]
        if all(results):
            matched = True
    return matched

def merge_intervals(intervals: list[tuple[int, int, str]]) -> list[tuple[int, int, list[str]]]:
    items = []
    for start, end, label in intervals:
        if not start < end:
            raise ValueError("start must be less than end")
        items.append((start, end, label))
    items.sort(key=lambda t: (t[0], t[1]))
    merged = []
    for start, end, label in items:
        if merged and start <= merged[-1][1]:
            s, e, labels = merged[-1]
            labels.add(label)
            merged[-1] = (s, max(e, end), labels)
        else:
            merged.append((start, end, {label}))
    return [(s, e, sorted(labels)) for s, e, labels in merged]

from datetime import datetime, timedelta

_LIMITS = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 6)]


def _num(text):
    if not (text.isascii() and text.isdigit()):
        raise ValueError(f"bad number: {text!r}")
    return int(text)


def _field(text, lo, hi):
    values = set()
    for item in text.split(","):
        if not item:
            raise ValueError("empty item")
        base, slash, step_text = item.partition("/")
        step = _num(step_text) if slash else 1
        if step < 1:
            raise ValueError("step must be >= 1")
        if base == "*":
            a, b = lo, hi
        elif "-" in base:
            a_text, _, b_text = base.partition("-")
            a, b = _num(a_text), _num(b_text)
            if a > b:
                raise ValueError("descending range")
        else:
            if slash:
                raise ValueError("steps need '*' or a range")
            a = b = _num(base)
        if a < lo or b > hi:
            raise ValueError("value out of range")
        values.update(range(a, b + 1, step))
    return values


def next_run(expr: str, after: str) -> str:
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("expected 5 fields")
    minutes, hours, doms, months, dows = (_field(f, lo, hi) for f, (lo, hi) in zip(fields, _LIMITS))
    dom_any, dow_any = fields[2] == "*", fields[4] == "*"
    start = datetime.strptime(after, "%Y-%m-%d %H:%M") + timedelta(minutes=1)
    day = start.date()
    last_day = day + timedelta(days=5 * 366)
    hour_list, minute_list = sorted(hours), sorted(minutes)
    while day <= last_day:
        if day.month in months:
            dom_ok = day.day in doms
            dow_ok = (day.weekday() + 1) % 7 in dows
            if dom_any and dow_any:
                ok = True
            elif dom_any:
                ok = dow_ok
            elif dow_any:
                ok = dom_ok
            else:
                ok = dom_ok or dow_ok
            if ok:
                for h in hour_list:
                    for m in minute_list:
                        cand = datetime(day.year, day.month, day.day, h, m)
                        if cand >= start:
                            return cand.strftime("%Y-%m-%d %H:%M")
        day += timedelta(days=1)
    raise ValueError("no matching time within 5 years")

def parse_csv_line(line: str, delimiter: str = ",") -> list[str]:
    if not isinstance(delimiter, str) or len(delimiter) != 1 or delimiter == '"':
        raise ValueError("delimiter must be one character other than '\"'")
    fields = []
    i, n = 0, len(line)
    while True:
        if i < n and line[i] == '"':
            i += 1
            buf = []
            while True:
                if i >= n:
                    raise ValueError("unterminated quoted field")
                ch = line[i]
                if ch == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        buf.append('"')
                        i += 2
                        continue
                    i += 1
                    break
                buf.append(ch)
                i += 1
            fields.append("".join(buf))
            if i == n:
                return fields
            if line[i] != delimiter:
                raise ValueError("unexpected text after closing quote")
            i += 1
        else:
            j = i
            while j < n and line[j] != delimiter:
                if line[j] == '"':
                    raise ValueError("quote inside unquoted field")
                j += 1
            fields.append(line[i:j])
            if j == n:
                return fields
            i = j + 1

import re

_INDEX = re.compile(r"0|[1-9][0-9]*")
_BAD_ESCAPE = re.compile(r"~(?![01])")


def resolve_pointer(doc, pointer: str):
    if pointer == "":
        return doc
    if not pointer.startswith("/"):
        raise ValueError("pointer must start with '/'")
    current = doc
    for raw in pointer[1:].split("/"):
        if _BAD_ESCAPE.search(raw):
            raise ValueError(f"invalid escape in {raw!r}")
        token = raw.replace("~1", "/").replace("~0", "~")
        if isinstance(current, dict):
            if token not in current:
                raise KeyError(token)
            current = current[token]
        elif isinstance(current, list):
            if token == "-":
                raise KeyError("-")
            if not _INDEX.fullmatch(token):
                raise ValueError(f"invalid array index {token!r}")
            index = int(token)
            if index >= len(current):
                raise KeyError(token)
            current = current[index]
        else:
            raise KeyError(token)
    return current

from functools import lru_cache


def _tokens(pattern):
    toks = []
    i, n = 0, len(pattern)
    while i < n:
        c = pattern[i]
        if c == "\\" and i + 1 < n:
            toks.append(("lit", pattern[i + 1]))
            i += 2
        elif c == "*":
            if i + 1 < n and pattern[i + 1] == "*":
                toks.append(("any",))
                i += 2
            else:
                toks.append(("star",))
                i += 1
        elif c == "?":
            toks.append(("one",))
            i += 1
        elif c == "[":
            j = i + 1
            negate = j < n and pattern[j] in "!^"
            if negate:
                j += 1
            k = j + 1 if j < n and pattern[j] == "]" else j
            while k < n and pattern[k] != "]":
                k += 1
            if k >= n:
                toks.append(("lit", "["))
                i += 1
                continue
            body = pattern[j:k]
            ranges = []
            p = 0
            while p < len(body):
                if p + 2 < len(body) and body[p + 1] == "-":
                    ranges.append((body[p], body[p + 2]))
                    p += 3
                else:
                    ranges.append((body[p], body[p]))
                    p += 1
            toks.append(("set", negate, tuple(ranges)))
            i = k + 1
        else:
            toks.append(("lit", c))
            i += 1
    return toks


def glob_match(pattern: str, name: str) -> bool:
    toks = _tokens(pattern)

    @lru_cache(maxsize=None)
    def match(ti, ni):
        if ti == len(toks):
            return ni == len(name)
        tok = toks[ti]
        kind = tok[0]
        if kind == "star":
            if match(ti + 1, ni):
                return True
            return ni < len(name) and name[ni] != "/" and match(ti, ni + 1)
        if kind == "any":
            if match(ti + 1, ni):
                return True
            return ni < len(name) and match(ti, ni + 1)
        if ni >= len(name):
            return False
        ch = name[ni]
        if kind == "lit":
            ok = ch == tok[1]
        elif kind == "one":
            ok = ch != "/"
        else:
            _, negate, ranges = tok
            inside = any(a <= ch <= b for a, b in ranges)
            ok = ch != "/" and inside != negate
        return ok and match(ti + 1, ni + 1)

    return match(0, 0)

import ipaddress
import re

_SYNTAX = re.compile(r"[0-9]{1,3}(?:\.[0-9]{1,3}){3}/[0-9]{1,2}")


def _block(text):
    if not isinstance(text, str) or not _SYNTAX.fullmatch(text):
        raise ValueError(f"malformed CIDR block: {text!r}")
    try:
        return ipaddress.IPv4Network(text, strict=True)
    except (ipaddress.AddressValueError, ipaddress.NetmaskValueError, ValueError) as exc:
        raise ValueError(str(exc)) from None


def cidr_subtract(base: str, remove: list[str]) -> list[str]:
    pieces = [_block(base)]
    for r in [_block(x) for x in remove]:
        nxt = []
        for p in pieces:
            if p.subnet_of(r):
                continue
            if r.subnet_of(p):
                nxt.extend(p.address_exclude(r))
            else:
                nxt.append(p)
        pieces = nxt
    merged = ipaddress.collapse_addresses(pieces)
    return [str(n) for n in sorted(merged, key=lambda n: (int(n.network_address), n.prefixlen))]

from fractions import Fraction


def _tokenize(expr):
    tokens = []
    i, n = 0, len(expr)
    while i < n:
        c = expr[i]
        if c in " \t\n\r":
            i += 1
        elif "0" <= c <= "9":
            j = i
            while j < n and "0" <= expr[j] <= "9":
                j += 1
            tokens.append(("num", int(expr[i:j])))
            i = j
        elif expr.startswith("**", i):
            tokens.append(("op", "**"))
            i += 2
        elif c in "+-*/()":
            tokens.append(("op", c))
            i += 1
        else:
            raise ValueError(f"unexpected character {c!r}")
    return tokens


def evaluate(expr: str) -> Fraction:
    tokens = _tokenize(expr)
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else (None, None)

    def take():
        nonlocal pos
        tok = peek()
        if tok[0] is None:
            raise ValueError("unexpected end of expression")
        pos += 1
        return tok

    def parse_expr():
        value = parse_term()
        while peek() in (("op", "+"), ("op", "-")):
            op = take()[1]
            rhs = parse_term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def parse_term():
        value = parse_unary()
        while peek() in (("op", "*"), ("op", "/")):
            op = take()[1]
            rhs = parse_unary()
            value = value * rhs if op == "*" else value / rhs
        return value

    def parse_unary():
        if peek() in (("op", "+"), ("op", "-")):
            op = take()[1]
            value = parse_unary()
            return value if op == "+" else -value
        return parse_power()

    def parse_power():
        base = parse_atom()
        if peek() == ("op", "**"):
            take()
            exponent = parse_unary()
            if exponent.denominator != 1:
                raise ValueError("exponent must be an integer")
            return base ** int(exponent)
        return base

    def parse_atom():
        kind, value = take()
        if kind == "num":
            return Fraction(value)
        if value == "(":
            inner = parse_expr()
            if take() != ("op", ")"):
                raise ValueError("expected ')'")
            return inner
        raise ValueError(f"unexpected token {value!r}")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("unexpected trailing input")
    return result

def osa_distance(a: str, b: str) -> int:
    n, m = len(a), len(b)
    d = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        d[i][0] = i
    for j in range(m + 1):
        d[0][j] = j
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            cost = 0 if a[i - 1] == b[j - 1] else 1
            d[i][j] = min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + cost)
            if i > 1 and j > 1 and a[i - 1] == b[j - 2] and a[i - 2] == b[j - 1]:
                d[i][j] = min(d[i][j], d[i - 2][j - 2] + 1)
    return d[n][m]

import re
from datetime import date, datetime, timedelta

_FORMAT = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")


def _date(text):
    if not isinstance(text, str) or not _FORMAT.fullmatch(text):
        raise ValueError(f"bad date: {text!r}")
    return datetime.strptime(text, "%Y-%m-%d").date()


def add_business_days(start: str, days: int, holidays: list[str]) -> str:
    current = _date(start)
    off = {_date(h) for h in holidays}

    def is_business(d: date) -> bool:
        return d.weekday() < 5 and d not in off

    if days == 0:
        while not is_business(current):
            current += timedelta(days=1)
        return current.isoformat()
    step = timedelta(days=1 if days > 0 else -1)
    remaining = abs(days)
    while remaining:
        current += step
        if is_business(current):
            remaining -= 1
    return current.isoformat()

from fractions import Fraction


def token_bucket(capacity: int, refill_per_sec: float, requests: list[tuple[float, int]]) -> list[bool]:
    if not isinstance(capacity, int) or capacity < 1:
        raise ValueError("capacity must be an integer >= 1")
    if refill_per_sec < 0:
        raise ValueError("refill rate must be >= 0")
    rate = Fraction(refill_per_sec)
    full = Fraction(capacity)
    tokens = full
    last = None
    allowed = []
    for timestamp, cost in requests:
        if not isinstance(cost, int) or isinstance(cost, bool) or cost < 1:
            raise ValueError("cost must be an integer >= 1")
        now = Fraction(timestamp)
        if last is not None:
            if now < last:
                raise ValueError("timestamps must be non-decreasing")
            tokens = min(full, tokens + (now - last) * rate)
        last = now
        if tokens >= cost:
            tokens -= cost
            allowed.append(True)
        else:
            allowed.append(False)
    return allowed

import heapq


def topo_order(nodes: list[str], edges: list[tuple[str, str]]) -> list[str]:
    if len(set(nodes)) != len(nodes):
        raise ValueError("duplicate nodes")
    successors = {n: set() for n in nodes}
    indegree = {n: 0 for n in nodes}
    for a, b in edges:
        if a not in successors or b not in successors:
            raise ValueError("edge mentions an unknown node")
        if a == b:
            raise ValueError("cycle (self-loop)")
        if b not in successors[a]:
            successors[a].add(b)
            indegree[b] += 1
    heap = [n for n in nodes if indegree[n] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        n = heapq.heappop(heap)
        order.append(n)
        for m in successors[n]:
            indegree[m] -= 1
            if indegree[m] == 0:
                heapq.heappush(heap, m)
    if len(order) != len(nodes):
        raise ValueError("cycle")
    return order

def wrap_text(text: str, width: int) -> list[str]:
    if width < 1:
        raise ValueError("width must be >= 1")
    lines = []
    current = ""
    for word in text.split():
        if len(word) > width:
            if current:
                lines.append(current)
            pieces = [word[i:i + width] for i in range(0, len(word), width)]
            lines.extend(pieces[:-1])
            current = pieces[-1]
        elif not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines

import re

_RANGE = re.compile(r"\*|[A-Za-z]{1,8}(?:-[A-Za-z0-9]{1,8})*")
_QVALUE = re.compile(r"0(?:\.[0-9]{0,3})?|1(?:\.0{0,3})?")


def negotiate_language(header: str, available: list[str]) -> str | None:
    ranges = []
    for position, entry in enumerate(header.split(",")):
        entry = entry.strip()
        if not entry:
            continue
        parts = entry.split(";")
        tag = parts[0].strip()
        if not _RANGE.fullmatch(tag):
            raise ValueError(f"malformed language range {tag!r}")
        quality = 1.0
        for param in parts[1:]:
            name, eq, value = param.partition("=")
            if not eq or name.strip().lower() != "q":
                raise ValueError(f"unsupported parameter {param!r}")
            value = value.strip()
            if not _QVALUE.fullmatch(value):
                raise ValueError(f"malformed q value {value!r}")
            quality = float(value)
        ranges.append((tag.lower(), quality, position))

    best = None
    for index, tag in enumerate(available):
        lowered = tag.lower()
        chosen = None
        for rng, quality, position in ranges:
            if rng == "*":
                specificity = 0
            elif lowered == rng or lowered.startswith(rng + "-"):
                specificity = len(rng)
            else:
                continue
            if chosen is None or specificity > chosen[0]:
                chosen = (specificity, quality, position)
        if chosen is None or chosen[1] == 0:
            continue
        key = (chosen[1], -chosen[2], -index)
        if best is None or key > best[0]:
            best = (key, tag)
    return best[1] if best else None

import re
from functools import cmp_to_key

_RUNS = re.compile(r"[0-9]+|[^0-9]+")


def _compare(a, b):
    ra, rb = _RUNS.findall(a), _RUNS.findall(b)
    for x, y in zip(ra, rb):
        xd, yd = x[0] in "0123456789", y[0] in "0123456789"
        if xd and yd:
            if int(x) != int(y):
                return -1 if int(x) < int(y) else 1
            if len(x) != len(y):
                return -1 if len(x) < len(y) else 1
        elif xd != yd:
            return -1 if xd else 1
        else:
            xl, yl = x.lower(), y.lower()
            if xl != yl:
                return -1 if xl < yl else 1
    if len(ra) != len(rb):
        return -1 if len(ra) < len(rb) else 1
    if a != b:
        return -1 if a < b else 1
    return 0


def natural_sort(items: list[str]) -> list[str]:
    return sorted(items, key=cmp_to_key(_compare))

def lfu_cache(capacity: int, ops: list[tuple]) -> list:
    if not isinstance(capacity, int) or capacity < 0:
        raise ValueError("capacity must be >= 0")
    store = {}  # key -> [value, uses, last_used_tick]
    tick = 0
    results = []
    for op in ops:
        if not isinstance(op, tuple) or not op:
            raise ValueError(f"bad operation {op!r}")
        tick += 1
        if op[0] == "get" and len(op) == 2:
            entry = store.get(op[1])
            if entry is None:
                results.append(None)
            else:
                entry[1] += 1
                entry[2] = tick
                results.append(entry[0])
        elif op[0] == "put" and len(op) == 3:
            _, key, value = op
            if capacity == 0:
                continue
            if key in store:
                entry = store[key]
                entry[0] = value
                entry[1] += 1
                entry[2] = tick
            else:
                if len(store) >= capacity:
                    victim = min(store, key=lambda k: (store[k][1], store[k][2]))
                    del store[victim]
                store[key] = [value, 1, tick]
        else:
            raise ValueError(f"bad operation {op!r}")
    return results

def split_sql(script: str) -> list[str]:
    statements = []
    buf = []

    def flush():
        text = "".join(buf).strip()
        if text:
            statements.append(text)
        buf.clear()

    i, n = 0, len(script)
    while i < n:
        c = script[i]
        if c in ("'", '"'):
            j = i + 1
            while True:
                if j >= n:
                    raise ValueError("unterminated quoted text")
                if script[j] == c:
                    if j + 1 < n and script[j + 1] == c:
                        j += 2
                        continue
                    break
                j += 1
            buf.append(script[i:j + 1])
            i = j + 1
        elif script.startswith("--", i):
            newline = script.find("\n", i)
            i = n if newline == -1 else newline
        elif script.startswith("/*", i):
            end = script.find("*/", i + 2)
            if end == -1:
                raise ValueError("unterminated block comment")
            buf.append(" ")
            i = end + 2
        elif c == ";":
            flush()
            i += 1
        else:
            buf.append(c)
            i += 1
    flush()
    return statements

import re

_TIME = re.compile(r"([01][0-9]|2[0-3]):([0-5][0-9])")


def _minutes(text):
    m = _TIME.fullmatch(text) if isinstance(text, str) else None
    if not m:
        raise ValueError(f"bad time: {text!r}")
    return int(m.group(1)) * 60 + int(m.group(2))


def _fmt(minutes):
    return f"{minutes // 60:02d}:{minutes % 60:02d}"


def first_common_slot(busy: list[list[tuple[str, str]]], day_start: str, day_end: str, duration_min: int) -> str | None:
    start, end = _minutes(day_start), _minutes(day_end)
    if end <= start:
        raise ValueError("day_end must be after day_start")
    if not isinstance(duration_min, int) or duration_min < 1:
        raise ValueError("duration must be >= 1")
    intervals = []
    for person in busy:
        for a_text, b_text in person:
            a, b = _minutes(a_text), _minutes(b_text)
            if b <= a:
                raise ValueError("busy interval must end after it starts")
            intervals.append((a, b))
    intervals.sort()
    t = start
    for a, b in intervals:
        if b <= t:
            continue
        if min(a, end) - t >= duration_min:
            return _fmt(t)
        t = max(t, b)
        if t >= end:
            return None
    return _fmt(t) if end - t >= duration_min else None
